package local.pitv;
import android.content.*;import android.media.*;import android.net.*;import java.util.*;
final class StreamInfo {
 static String technical(MediaPlayer media,boolean ready){StringBuilder technical=new StringBuilder("LIVE");if(media!=null&&ready)try{int width=media.getVideoWidth(),height=media.getVideoHeight();if(width>0&&height>0)technical.append("  ·  ").append(width).append(" × ").append(height);boolean rate=false;MediaPlayer.TrackInfo[] all=media.getTrackInfo();for(int trackIndex=0;trackIndex<all.length;trackIndex++){MediaPlayer.TrackInfo track=all[trackIndex];android.media.MediaFormat format=track.getFormat();if(format==null)continue;if(track.getTrackType()==MediaPlayer.TrackInfo.MEDIA_TRACK_TYPE_VIDEO){if(format.containsKey(android.media.MediaFormat.KEY_MIME))technical.append("  ·  ").append(format.getString(android.media.MediaFormat.KEY_MIME).replace("video/",""));if(format.containsKey(android.media.MediaFormat.KEY_FRAME_RATE))technical.append("  ·  ").append(format.getInteger(android.media.MediaFormat.KEY_FRAME_RATE)).append(" fps");if(format.containsKey(android.media.MediaFormat.KEY_BIT_RATE)){int bitrate=format.getInteger(android.media.MediaFormat.KEY_BIT_RATE);if(bitrate>0){technical.append("  ·  ").append(String.format(Locale.ROOT,"%.2f Mb/s",bitrate/1000000f));rate=true;}}}if(track.getTrackType()==MediaPlayer.TrackInfo.MEDIA_TRACK_TYPE_AUDIO){int selected=media.getSelectedTrack(MediaPlayer.TrackInfo.MEDIA_TRACK_TYPE_AUDIO);if(selected==trackIndex){String language=track.getLanguage();if(language!=null&&!language.equals("und"))technical.append("  ·  Audio ").append(language);if(format.containsKey(android.media.MediaFormat.KEY_CHANNEL_COUNT))technical.append("  ·  ").append(format.getInteger(android.media.MediaFormat.KEY_CHANNEL_COUNT)).append(" ch");}}}if(!rate)technical.append("  ·  Bitrate unavailable");}catch(Exception ignored){}else technical.append("  ·  ").append(ready?"Playing":"Connecting");return technical.toString();}
 static String connection(Context context,String url){String source="Source unavailable";try{Uri address=Uri.parse(url);String scheme=address.getScheme(),host=address.getHost();if(host!=null)source="Source: "+scheme.toUpperCase(Locale.ROOT)+" · "+host+" · "+(address.getPath()!=null&&address.getPath().endsWith(".m3u8")?"HLS":address.getPath()!=null&&address.getPath().endsWith(".ts")?"MPEG-TS":"Live stream");}catch(Exception ignored){}String network="Network unavailable";try{android.net.ConnectivityManager cm=(android.net.ConnectivityManager)context.getSystemService(Context.CONNECTIVITY_SERVICE);android.net.NetworkCapabilities capabilities=cm.getNetworkCapabilities(cm.getActiveNetwork());if(capabilities!=null){if(capabilities.hasTransport(android.net.NetworkCapabilities.TRANSPORT_ETHERNET))network="Ethernet";else if(capabilities.hasTransport(android.net.NetworkCapabilities.TRANSPORT_WIFI)){network="Wi-Fi";try{android.net.wifi.WifiManager wifi=(android.net.wifi.WifiManager)context.getApplicationContext().getSystemService(Context.WIFI_SERVICE);int rssi=wifi.getConnectionInfo().getRssi();if(rssi>-127&&rssi<0)network+=" · Signal "+rssi+" dBm";}catch(Exception ignored){}}else network="Connected network";}}catch(Exception ignored){}return source+"\n"+network;}
}
